Definition find_atA (entry : Z) : Prop :=
  forall (fx : PropExec.FPState) (A : AS MI_A) (R : bvmap 5 word) (M : mem) (obj bl bc keyp key sp k0 : Z) (ents : list (Z * (Z * Z))) (ret : word),
    umapx MI_A 24 (nval24 ASEGS) A M obj bl bc ents -> 24 <= 24 ->
    cell4 ASEGS M keyp key -> 0 < keyp -> keyp + 4 <= 2 ^ 47 ->
    (forall i, GOT_SH <= i < GOT_SH + 8 -> M (Z_to_bv 64 i) = None) -> cell8 ASEGS M SHCELL SHBASE ->
    gz M obj 40 -> (bc <> 0 -> gz M bl (8 * bc)) -> (forall p k v, In (p, (k, v)) ents -> gz M p 24) ->
    shk M keyp k0 -> (k0 = 0 \/ (0 < k0 < 8 /\ keyp mod 8 + 3 < k0)) ->
    sp mod 16 = 0 -> 2 ^ 45 <= sp - 16 -> sp <= 2 ^ 47 -> LibIface.stack_room ASEGS M sp 16 ->
    apart (sp - 16) 16 obj 40 -> apart (sp - 16) 16 keyp 4 -> (bc <> 0 -> apart (sp - 16) 16 bl (8 * bc)) ->
    (forall p k v, In (p, (k, v)) ents -> apart (sp - 16) 16 p 24) ->
    PropExec.getr R 10%bv = Z_to_bv 64 obj -> PropExec.getr R 11%bv = Z_to_bv 64 keyp -> PropExec.getr R 2%bv = Z_to_bv 64 sp ->
    PropExec.getr R 1%bv = ret -> Hoare.ret_ok ret ->
    exists R' (p : Z),
      CatSim.msteps ASEGS (@PropExec.mkst fx R (Z_to_bv 64 entry) M (PropExec.seg_rom ASEGS))
                          (@PropExec.mkst fx R' ret (CatExec.wbytes M (Z_to_bv 64 (sp - 8)) (word_to_le_bytes 8 ret)) (PropExec.seg_rom ASEGS))
      /\ RefMemcpyLib.keeps_cs R R' /\ PropExec.getr R' 10%bv = Z_to_bv 64 p /\ (p = 0 \/ exists v, In (p, (key, v)) ents).

