  Lemma pm_find_m1 : forall (w : pmwA H) s LB LBs m mo c ins tbl ftbl TB spal msF R F fc (ret keyp key : Z) (Q : config -> Prop),
    pmw_okA H w -> PMXAT H LINV w s LB LBs m mo c ins tbl ftbl TB spal ->
    keys_nonneg (map fst tbl) = true -> fkeys_ok (map fst ftbl) = true ->
    as_AKREL H s (mkCfg msF mo) -> as_VIS H s msF = MS R F (Z_to_bv 64 LbB_HFind.FIND) fc None m (seg_rom asegs) -> rfull R ->
    PropExec.getr R 2%bv = Z_to_bv 64 (wa_s1 w) -> PropExec.getr R 1%bv = Z_to_bv 64 ret -> ret mod 2 = 0 -> 0 <= ret < 2 ^ 64 ->
    PropExec.getr R 10%bv = Z_to_bv 64 (wa_p w + O_M1) -> PropExec.getr R 11%bv = Z_to_bv 64 keyp ->
    rw_cells asegs m keyp [C4 (Z_to_bv 64 key)] -> 0 <= key < 2 ^ 32 -> accessible m keyp 4 -> keyp mod 4 = 0 ->
    0 < keyp -> (keyp + 4 <= wa_s1 w - 16 \/ wa_s1 w <= keyp) -> keyp + 4 <= 2 ^ 47 ->
    (forall msF1 mo1 m1 R1 (p : Z), as_AKREL H s (mkCfg msF1 mo1) ->
       as_VIS H s msF1 = MS R1 F (Z_to_bv 64 ret) fc None m1 (seg_rom asegs) -> rfull R1 ->
       PMXAT H LINV w s LB LBs m1 mo1 c ins tbl ftbl TB spal ->
       (forall r, In r KEPT_REGS -> PropExec.getr R1 r = PropExec.getr R r) ->
       PropExec.getr R1 10%bv = Z_to_bv 64 p ->
       (p = 0 \/ (0 < p /\ p + 24 <= aceil /\ p mod 16 = 0 /\ addressable m1 p 24 /\
                  exists v, In (p, (key, v)) (t3c (c_m1 c)) /\ 0 <= v < 2 ^ 32 /\ HRep.cellw ASEGS m1 (p + 20) 4 v)) ->
       munch [(wa_s1 w - 16, wa_s1 w)] m m1 -> wmono asegs m m1 ->
       (forall k cs, 0 <= k -> k + Z.of_nat (cells_size cs) <= 16384 -> rw_cells asegs m (wa_ff w + k) cs -> rw_cells asegs m1 (wa_ff w + k) cs) ->
       as_SR H Q (mkCfg msF1 mo1)) ->
    as_SR H Q (mkCfg msF mo).
Proof.
